// Lantern Tunnel - a flight down a twisting tunnel of glowing veils toward a
// flickering lantern, seen as a full 360-degree panorama. Parametric (u,v),
// animated. Seam-free.
//
// HOW IT CLOSES: every point of the surface looks along a direction of
// space: u turns the gaze around the tunnel axis, v tilts it from straight
// ahead (toward the lantern) to straight back. u = 0 and u = 1 are the same
// direction, and looking straight ahead/back every u sees the same thing:
// no seam, no pinch.
//   PITCH_LOOP = 1: v goes ahead -> back -> ahead: closes on every surface
//                   (torus, Klein bottle, Moebius band...).
//   PITCH_LOOP = 0: v goes once from ahead to back: an exact panorama on
//                   sphere-like surfaces whose v runs from pole to pole.
// The veils are thin shells around the zero set of a gyroid
// (sin x cos y + sin y cos z + sin z cos x), twisted along the axis and carved
// away around it. Light is gathered along each ray (volumetric glow): close
// veils shine, far ones fade, and those near the lantern take its color.
// Dock colors: u_col1 = lantern light, u_col2 = haze of the depths.

const float PITCH_LOOP = 1.0;  // see above
const float SPEED    = 0.5;    // flight speed (units per second)
const float ROLL     = 0.01;   // slow roll of the view (turns per second)
const float SCALE    = 1.6;    // density of the veils                  [0.8 .. 3]
const float THICK    = 0.05;   // thickness of the veils                [0.01 .. 0.2]
const float RADIUS   = 0.7;    // free radius of the tunnel             [0.3 .. 1.2]
const float TWIST    = 0.35;   // twist of the tunnel along its axis    [0 .. 1]
const float AHEAD    = 2.5;    // distance of the lantern               [1 .. 6]
const float BRIGHT   = 5.0;    // brightness of the veils               [0.5 .. 10]
const float HALO     = 1.0;    // size and strength of the lantern halo [0 .. 3]
const vec3  PALETTE  = vec3(0.6, 2.0, 3.2); // R,G,B phases of the veil colors
const int   STEPS    = 70;     // ray steps: quality against speed      [32 .. 120]

float veils(vec3 p) {
    float a = TWIST * p.z;
    vec2 xy = mat2(cos(a), sin(a), -sin(a), cos(a)) * p.xy;
    vec3 q = vec3(xy, p.z) * SCALE;
    float gyroid = dot(sin(q), cos(q.yzx)) / SCALE;
    float shell = abs(gyroid) - THICK;
    float carve = RADIUS - length(xy);              // > 0 inside the free tube
    return max(shell, carve);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float time = iTime;

    // gaze direction from (u, v): theta = 0 straight ahead (+z)
    float tri = 1.0 - abs(2.0 * fract(uv.y) - 1.0);        // 0 -> 1 -> 0 along v
    float w = PITCH_LOOP > 0.5 ? tri : clamp(uv.y, 0.0, 1.0);
    float theta = PI * w;
    float phi = TAU * (uv.x + ROLL * time);
    vec3 dir = vec3(sin(theta) * cos(phi), sin(theta) * sin(phi), cos(theta));

    vec3 ro = vec3(0.0, 0.0, SPEED * time);
    vec3 lantern = ro + vec3(0.15 * sin(0.9 * time), 0.12 * cos(1.3 * time), AHEAD);
    float flicker = 0.85 + 0.15 * sin(6.0 * time + 2.0 * sin(2.3 * time));

    vec3 acc = vec3(0.0);
    float z = 0.0;
    for (int i = 0; i < STEPS; i++) {
        vec3 p = ro + dir * z;
        float dist = veils(p);
        float ad = max(abs(dist), 0.005);
        vec3 tint = 1.0 + cos(0.8 * p.z + PALETTE);
        vec3 lp = p - lantern;
        float lit = 6.0 * flicker / (1.0 + 1.5 * dot(lp, lp));
        acc += (0.6 * tint + lit * u_col1) / ad;
        z += max(abs(dist) * 0.7, 0.01);
    }
    vec3 col = acc * (BRIGHT / (float(STEPS) * 400.0));
    col += u_col2 * 0.12;

    // the lantern itself: how close the gaze passes to it
    vec3 wv = lantern - ro;
    float along = dot(wv, dir);
    float miss2 = max(dot(wv, wv) - along * along, 0.0);
    float halo = 0.03 * HALO / (miss2 + 0.006 * HALO);              // soft halo
    halo += 0.004 / (miss2 + 0.0003);                                  // hot core
    if (along > 0.0) col += u_col1 * flicker * halo;

    col = 1.0 - exp(-col);                          // soft roll-off of the highlights
    fragColor = vec4(col, 1.0);
}
